import json, time, sys
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
PAGES = {
 "https://acme-robotics.test/about": "About: Acme\n\nAcme Robotics was founded in 2014. Acme Robotics is headquartered in Lisbon. Acme Robotics employs about 120 people. Acme Robotics has raised $12M. Acme Robotics legal name is Acme Robotics, Inc. Dana Ruiz has led Acme Robotics as chief executive since 2021.",
 "https://acme-robotics.test/team": "Team: Acme\n\nAcme Robotics CEO: Sam Ortiz. Acme Robotics is based in Porto.",
}
class H(BaseHTTPRequestHandler):
    def log_message(self,*a): print('LOG',*a, flush=True)
    def _send(self,obj,status=200):
        b=json.dumps(obj).encode()
        self.send_response(status); self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(b))); self.end_headers(); self.wfile.write(b)
    def do_POST(self):
        n=int(self.headers.get('Content-Length') or 0); raw=self.rfile.read(n)
        print('POST',self.path,raw[:300],flush=True)
        try: body=json.loads(raw or b'{}')
        except Exception: body={}
        if self.path.startswith('/v2/search'):
            time.sleep(0.5)
            results=[{"url":u,"title":u,"description":t[:80],"content":t} for u,t in PAGES.items()]
            return self._send({"results":results})
        if '/agents' in self.path:
            return self._send({"error":{"message":"refused"}},400)
        return self._send({"error":{"message":"not found"}},404)
    def do_GET(self):
        print('GET',self.path,flush=True)
        if '/agents/' in self.path and self.path.endswith('/result'):
            return self._send({"output":{"type":"object","content":{"ceo":"Dana Ruiz"}}})
        return self._send({"error":{"message":"not found"}},404)
ThreadingHTTPServer(('127.0.0.1',19092),H).serve_forever()
